function longestSubarray(nums) {
  let maxValue = 0;
  let best = 0;
  let run = 0;

  for (const value of nums) {
    if (value > maxValue) {
      maxValue = value;
      best = 0;
      run = 0;
    }
    if (value === maxValue) {
      run++;
      best = Math.max(best, run);
    } else {
      run = 0;
    }
  }
  return best;
}

