function longestSubarray(nums) {
  let topAnd = -1;
  let longest = 0;
  for (let start = 0; start < nums.length; start++) {
    let acc = nums[start];
    for (let end = start; end < nums.length; end++) {
      acc &= nums[end];
      const len = end - start + 1;
      if (acc > topAnd) {
        topAnd = acc;
        longest = len;
      } else if (acc === topAnd && len > longest) {
        longest = len;
      }
    }
  }
  return longest;
}

